mapper.update:
UPDATE agent_task
SET status = #{status},
    error_message = #{errorMessage},
    finished_at = #{finishedAt}
WHERE task_id = #{taskId}

mapper.select:
SELECT task_id, tenant_id, user_id, session_id, task_type, status, error_message
FROM agent_task
WHERE user_id = #{userId}
  AND tenant_id = #{tenantId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}
